        #region Constructor

        internal ReportAnalytePanel(Report parent, TestAnalytePanel panel, string orderingPanelCode, SPMStatusValue spmStatus)
        {
            m_onLoadTransmitStatus = m_transmitStatus;
            m_auditItemList = new List<string>();
            m_parent = parent;
            m_panelCode = panel.PanelCode;
            m_spmStatus = (int)spmStatus;
            AddOrderingCode(orderingPanelCode);

            m_panel = new RefAnalytePanel(this);
            m_panel.Load(panel);
            // m_panel = panel

            m_comments = new ReportComments(this);
            m_orderAnalytes = new ReportAnalytes(this);
            // 'Code here create an OrderAnalytePanel from an AnalytePanel
            // ************************************************************
            foreach (Analyte a in panel.Analytes.List)
            {
                var oa = new ReportAnalyte(this, (TestAnalyte)a, "", spmStatus: spmStatus);
                Analytes.List.Add(oa);
            }
            // ************************************************************

            // Moved here so rules can fire properly
            parent.AnalytePanels.List.Add(this);

            // 'We do this after since we may need all the analytes when firing a rule.
            foreach (ReportAnalyte a in Analytes.List)
            {
                if (a.Analyte.IsRequired)
                {
                    Logger.Debug($"Calling EvaluateRulesEx with RuleSetRelease on {a.Code}");
                    parent.EvaluateRulesEx(a, "", Configuration.RuleSetRelease);
                }
            }
            InitializeToFollowSent(false);
            FlagDirty();
            FlagChild();
        }

        internal ReportAnalytePanel(Report parent, TestInfo testInfo, string orderingPanelCode, SPMStatusValue spmStatus)
        {
            m_onLoadTransmitStatus = m_transmitStatus;
            m_auditItemList = new List<string>();
            m_parent = parent;
            m_panelCode = testInfo.Code;
            m_spmStatus = (int)spmStatus;
            AddOrderingCode(orderingPanelCode);

            m_panel = new RefAnalytePanel(this);
            m_panel.Load(testInfo);
            // m_panel = panel

            m_comments = new ReportComments(this);
            m_orderAnalytes = new ReportAnalytes(this);
            // 'Code here create an OrderAnalytePanel from an AnalytePanel
            // ************************************************************
            foreach (TestInfo ti in testInfo.Components)
            {
                var oa = new ReportAnalyte(this, ti, "", spmStatus: spmStatus);
                Analytes.List.Add(oa);
            }

            // Moved here so rules can fire properly
            parent.AnalytePanels.List.Add(this);

            // 'We do this after since we may need all the analytes when firing a rule.
            foreach (ReportAnalyte a in Analytes.List)
            {
                if (a.Analyte.IsRequired)
                {
                    Logger.Debug("Calling EvaluateRulesEx with RuleSetRelease");
                    parent.EvaluateRulesEx(a, "", Configuration.RuleSetRelease);
                }
            }
            // ************************************************************
            InitializeToFollowSent(testInfo.DoNotSendToFollow);
            FlagDirty();
            FlagChild();
        }

