        public delegate void UpdatePanelDelegate(ReportAnalytePanel panel, EventArgs arg);

        [NonSerialized()]
        private List<UpdatePanelDelegate> mNonSerializableHandlers = new List<UpdatePanelDelegate>();

        // We need to declare this custom event because we need to mark the delegates as nonSerializable - so
        // that the target object will not be attempted to be serialized.
        public event UpdatePanelDelegate UpdatePanelCompleted
        {

            add
            {

                if (mNonSerializableHandlers is null)
                {
                    mNonSerializableHandlers = new List<UpdatePanelDelegate>();
                }

                mNonSerializableHandlers.Add(value);

            }

            remove
            {

                if (!(mNonSerializableHandlers == null))
                {
                    mNonSerializableHandlers.Remove(value);
                }

            }

        }

        void OnUpdatePanelCompleted(ReportAnalytePanel panel, EventArgs arg)
        {
            if (!(mNonSerializableHandlers == null))
            {
                foreach (UpdatePanelDelegate item in mNonSerializableHandlers)
                    item.Invoke(panel, arg);
            }
        }

