        private void InitializeToFollowSent(bool notSendToFollow)
        {
            // ''''''''''''''''''''''''''''' To Follow'''''''''''''''''''''''''''''''''''''''''''''''''''''''''
            if (!Configuration.AppSettings.GetBool("Bioreference.LIS:ToFollowEnabled"))
            {
                m_toFollowSent = true;
                foreach (ReportAnalyte a in Analytes.List)
                    a.ToFollowSent = true;
                return;
            }

            if (!(m_parent == null) && m_parent.IsCOC)
            {
                m_toFollowSent = true;
            }
            // ElseIf Not IsNothing(m_panel) AndAlso m_panel.Category.ToLower().Equals("allergen") Then
            // Me.m_toFollowSent = True
            else if (!(m_panel == null) && m_panel.IsReportable && !notSendToFollow)
            {
                m_toFollowSent = false;
            }
            else
            {
                m_toFollowSent = true;
            }
            // '''' Loop on eachh analyte for the panel
            foreach (ReportAnalyte a in Analytes.List)
            {
                if (notSendToFollow)
                {
                    a.ToFollowSent = true;
                }
                else if (!(m_parent == null) && m_parent.IsCOC)
                {
                    a.ToFollowSent = true;
                }
                // ElseIf Not IsNothing(a) AndAlso a.Analyte.Category.ToLower().Equals("allergen") Then
                // a.ToFollowSent = True
                else if (!(a == null) && a.Analyte.IsReportable && a.Analyte.IsRequired)
                {
                    a.ToFollowSent = false;
                }
                else
                {
                    a.ToFollowSent = true;
                }
            }

            // ''''''''''''''''''''''''''''''''''''''''''''''''''''''''''''''''''''''''''''''''''''''''''''''''
        }

