        public void AddCommentForCommentUpdate(string commenttype)
        {
            if (HasBeenReleased())
            {
                AddComment(Conversions.ToString(FormatCommentForCommentUpdate(Configuration.LISSettings.GetString("AutomatedRevisedComment"), commenttype)));
            }
        }

        public object FormatCommentForCommentUpdate(string commenttext, string commenttype)
        {
            string Comment = "";
            if (commenttype == "Add")
            {
                Comment = string.Format(commenttext, "added to", Strings.Format(ReleaseDate, "MM/dd/yyyy"));
            }
            else if (commenttype == "Delete")
            {
                Comment = string.Format(commenttext, "deleted from", Strings.Format(ReleaseDate, "MM/dd/yyyy"));
            }
            return SharedFunctions.FormatCommentText(Comment, Configuration.LISSettings.GetInt("CommentUpdateMaxLength"));

        }

        public void RemoveAllComments()
        {
            foreach (ReportComment c in Comments.List)
            {
                Comments.List.Remove(c);
                RemoveAllComments();
                break;
            }
        }

        public void SetStatusToCorrected()
        {
            if (IsTestHold())
            {
                return;
            }
            foreach (ReportAnalyte a in Analytes.List)
            {
                // NA: When changing the status need to set the transmit status as well
                // If a.ResultStatus = resultStatusType.Final Then a.ResultStatus = resultStatusType.Corrected
                if (a.ResultStatus == resultStatusType.Final)
                {
                    a.ResultStatus = resultStatusType.Corrected;
                    a.SetTransmitStatus(transmitStatusType.PendingRelease);
                }
            }

        }

        [Obsolete("Needs to be changed, cannot have direct access to TransmitStatus")]
        internal void SetTransmitStatus(transmitStatusType status, bool updateAnalytes = true)
        {
            if (status != m_transmitStatus)
            {
                if (IsTestHold() & status > transmitStatusType.PendingRelease)
                {
                    return;
                }
                m_transmitStatus = status;
                if (status == transmitStatusType.Released)
                {
                    m_resetReleaseDate = true;
                    m_isPreliminaryReleased = false;
                }

                if (updateAnalytes)
                {
                    foreach (ReportAnalyte a in m_orderAnalytes.List)
                        a.SetTransmitStatus(status);
                }
                FlagDirty();
            }
        }

