        }

        public bool PanelIsPartiallyResulted()
        {
            return IsPartiallyResulted();
        }

        private bool IsPartiallyResulted()
        {
            int totalCount = 0;
            int resultedCount = 0;
            foreach (ReportAnalyte analyte in Analytes.List)
            {
                if (analyte.Analyte.IsRequired)
                {
                    if (analyte.ResultStatus == resultStatusType.Final)
                    {
                        return false;
                    }
                    totalCount += 1;
                    if (!string.IsNullOrEmpty(analyte.ResultValue))
                    {
                        resultedCount += 1;
                    }
                }
                if (resultedCount != 0 && resultedCount < totalCount)
                {
                    return true;
                }
            }
            return false;
        }

