        public bool ContainsOrderCode(string testCode)
        {

            return m_orderingPanelCodes.Contains(testCode);

        }

        public void AddOrderingCode(string testCode)
        {

            if (testCode.Equals(""))
                return;

            if (!m_orderingPanelCodes.Contains(testCode))
            {
                m_orderingPanelCodes.Add(testCode);

                if (HasBeenReleased())
                    MarkAsReleased();

                FlagDirty();
            }

        }

        public void RemoveOrderingCodes()
        {
            m_orderingPanelCodes.Clear();
        }

        public void RemoveOrderingCode(string testCode, bool deleteTestWithNoOrderables = true)
        {

            if (testCode.Equals(""))
                return;

            m_orderingPanelCodes.Remove(testCode);
            FlagDirty();

            if (deleteTestWithNoOrderables)
            {
                if (m_orderingPanelCodes.Count == 0)
                {
                    Parent.RemovePanel((int)Id);
                }
            }

        }

