        /// <summary>
    /// </summary>
    /// <remarks></remarks>
        public void MarkAsReleased()
        {
            // Removed if condition - need to be able to rerelease
            // If m_transmitStatus = transmitStatusType.PendingRelease OrElse m_transmitStatus = transmitStatusType.Released Then
            bool releaseFromUI;
            if (MarkedAsPreliminary)
            {
                MarkAsPreliminaryReleasedOnCondition((List<string>)Configuration.LISSettings.GetList("TestCodeListForPrelimRelease"));
            }
            else
            {
                foreach (ReportAnalyte a in m_orderAnalytes.List)
                {
                    releaseFromUI = a.ReleaseFromUI;
                    if (!string.IsNullOrEmpty(a.ResultValue))
                    {
                        if (m_releaseFromUI)
                        {
                            a.ReleaseFromUI = true;
                        }
                        a.MarkAsReleased();
                        if (a.IsDeltaHold)
                            a.ReleaseFromUI = releaseFromUI;
                    }
                }
                Logger.Debug($"Panel {PanelCode} IsTestHold={IsTestHold()}");
                if (!IsTestHold())
                {
                    Logger.Debug($"Panel {PanelCode} Releasing");
                    m_resetReleaseDate = true;
                    if (AnalytesReadyForRelease())
                        m_transmitStatus = transmitStatusType.Released;
                    m_isPreliminaryReleased = false;
                }
                FlagDirty();
            }
            // Else
            // Throw New Exception(String.Concat("Unable to set status to Released if status is ", m_transmitStatus))
            // End If
        }

        public void ReRelease(bool isCoc)
        {
            // only COC re-release is permitted for now via this route.
            if (!IsTestHold())
            {
                if (!isCoc)
                    return;

                foreach (ReportAnalyte a in m_orderAnalytes.List)
                {
                    if (!string.IsNullOrEmpty(a.ResultValue))
                        a.ReRelease(isCoc);
                }

                m_resetReleaseDate = true;
                if (AnalytesReadyForRelease())
                    m_transmitStatus = transmitStatusType.Released;
                m_isPreliminaryReleased = false;
                FlagDirty();
            }
        }

        /// <summary>
    /// Returns true if any analyte is in DeltaHold
    /// </summary>
    /// <returns></returns>
        public bool HoldReleaseForDeltaHold()
        {
            foreach (ReportAnalyte a in m_orderAnalytes.List)
            {
                if (a.ResultStatus == resultStatusType.DeltaHold)
                {
                    Logger.Debug($"Panel {PanelCode} Analyte {a.Code} is DeltaHold");
                    return true;
                }
            }
            return false;
        }

        private bool AnalytesReadyForRelease()
        {
            foreach (ReportAnalyte a in m_orderAnalytes.List)
            {
                if (a.Analyte.IsRequired && !a.HasBeenReleased())
                    return false;
            }
            return true;
        }

        public void MarkAsPreliminaryReleasedOnCondition(List<string> testCodeList)
        {
            if (!IsTestHold())
            {
                if (!((RefAnalytePanel)Panel).AllowPreliminaryRelease)
                {
                    throw new Exception("Unable to partial release a panel that does not allow partial releasing.");
                }

                foreach (ReportAnalyte a in m_orderAnalytes.List)
                {
                    if (!string.IsNullOrEmpty(a.ResultValue) && testCodeList.Contains(a.Code))
                        a.MarkAsPreliminaryReleased();
                }
                m_transmitStatus = transmitStatusType.Released;
                m_isPreliminaryReleased = true;
                m_resetReleaseDate = true;
                FlagDirty();
            }
        }

        public bool IsPanelSampleRequested()
        {
            bool returnval = false;
            foreach (ReportAnalyte a in m_orderAnalytes.List)
            {
                if (!string.IsNullOrEmpty(a.ResultValue) && a.ResultValue == "QNS" && (a.SampleStatus == (int)SampleRequestType.SampleRequest || a.SampleStatus == (int)SampleRequestType.SampleEnRoute))
                {
                    returnval = true;
                    break;
                }
            }
            return returnval;
        }

        public void MarkAsPreliminaryReleased()
        {
            if (!IsTestHold())
            {
                if (!((RefAnalytePanel)Panel).AllowPreliminaryRelease && !IsPanelSampleRequested())
                {
                    throw new Exception("Unable to partial release a panel that does not allow partial releasing.");
                }

                foreach (ReportAnalyte a in m_orderAnalytes.List)
                {
                    if (!string.IsNullOrEmpty(a.ResultValue))
                        a.MarkAsPreliminaryReleased();
                }
                m_transmitStatus = transmitStatusType.Released;
                m_isPreliminaryReleased = true;
                m_resetReleaseDate = true;
                FlagDirty();
            }
        }

        /// <summary>
    /// Exception will be thrown if ResultStatus is not Released Or PendingRelased.
    /// </summary>
    /// <remarks></remarks>
        public void MarkAsPendingRelease()
        {
            if (m_transmitStatus == transmitStatusType.Released || m_transmitStatus == transmitStatusType.PendingRelease)
            {
                foreach (ReportAnalyte a in m_orderAnalytes.List)
                    a.MarkAsPendingReleased();
                m_transmitStatus = transmitStatusType.PendingRelease;
                FlagDirty();
            }
            else
            {
                throw new Exception(string.Concat("Unable to set status to PendingReleased if status is ", m_transmitStatus));
            }
        }

        /// <summary>
    /// derived from ReportAnalyte list
    /// </summary>
        public resultStatusType GetStatus()
        {

            int x = 0;
            int i = (int)resultStatusType.Final;

            if (m_orderAnalytes.List.Count == 0)
                return resultStatusType.Pending;

            foreach (ReportAnalyte a in m_orderAnalytes.List)
            {
                if (a.Analyte.IsRequired)
                {
                    if (a.ResultStatus == resultStatusType.Corrected)
                        return resultStatusType.Corrected;
                    if (string.IsNullOrEmpty(a.ResultValue))
                        return resultStatusType.Pending; // 'For a result that was blanked out, then attempt to release panel
                    x = (int)a.ResultStatus;
                    if (x < i)
                        i = x;
                }
            }
            return (resultStatusType)i;
        }

        public bool IsTestHold()
        {
            if (m_orderAnalytes is null || m_orderAnalytes.List.Count == 0)
                return false;

            foreach (ReportAnalyte a in m_orderAnalytes.List)
            {
                // AG 9/17/08 - We only care about Required analytes.
                if (a.Analyte.IsRequired)
                {
                    if (a.IsTestHold)
                        return true;
                }
            }
            return false;
        }

        public DateTime GetLatestResultDate()
        {

            var d = DateTime.Parse("1900-01-01");
            foreach (ReportAnalyte a in m_orderAnalytes.List)
            {
                if (a.ResultDate > d)
                    d = a.ResultDate;
            }
            return d;

        }

