    /// </summary>
    /// <returns></returns>
    /// <remarks></remarks>
        public bool HasPreviousResultValues()
        {

            foreach (ReportAnalyte a in m_orderAnalytes.List)
            {
                if (!string.IsNullOrEmpty(a.PreviousResultValue))
                    return true;
            }
            return false;

        }

        public bool HasBeenReleased()
        {
            if (IsTestHold())
            {
                return false;
            }
            else if (m_transmitStatus == transmitStatusType.Released || m_transmitStatus == transmitStatusType.StatusSentToVertex || m_transmitStatus == transmitStatusType.SentToReporting || m_transmitStatus == transmitStatusType.ReadByReporting || m_transmitStatus == transmitStatusType.Reported)



            {
                return true;
            }
            else
            {
                return false;
            }

        }

        public bool HasAlerts()
        {

            foreach (ReportAnalyte a in Analytes.List)
            {
                if (a.Alerts.List.Count > 0)
                    return true;
            }
            return false;

        }

        public void CheckProcessing()
        {
            if (!(HasBeenReleased() && GetStatus() >= resultStatusType.Final && GetStatus() != resultStatusType.OnHold))
            {
                m_IsProcessing = true;
            }
        }

        public bool HasAlertsThatBlockAutoRelease()
        {

            foreach (ReportAnalyte a in Analytes.List)
            {
                if (a.HasAlertsThatBlockAutoRelease())
                    return true;
            }
            return false;

        }

