        #region Data Functions

        internal void Load(DataRow row)
        {

            m_id = Conversions.ToLong(row["ReportAnalytePanelID"]);
            m_panelCode = Conversions.ToString(row["PanelCode"]);
            m_transmitStatus = (transmitStatusType)Conversions.ToInteger(row["PanelTransmitStatus"]);
            m_onLoadTransmitStatus = m_transmitStatus;
            m_orderingPanelCodes.AddRange(row["OrderingPanelCode"].ToString().Split(','));
            m_criticalType = (criticalType)Conversions.ToInteger(row["PanelCriticalType"]); // aaa'
            m_releaseDate = Conversions.ToDate(row["PanelReleaseDate"]);

            if (row.Table.Columns.Contains("IsPreliminaryReleased"))
            {
                m_isPreliminaryReleased = Conversions.ToBoolean(row["IsPreliminaryReleased"]);
            }

            if (row.Table.Columns.Contains("MarkedAsPreliminary"))
            {
                m_markedAsPreliminary = Conversions.ToBoolean(row["MarkedAsPreliminary"]);
            }

            m_toFollowSent = Conversions.ToBoolean(row["PanelToFollowSent"]);
            m_SPMOrderTestId = Conversions.ToLong(row["SPMOrderTestId"]);

            m_panel = new RefAnalytePanel(this);
            m_panel.Load(row);


            // Demo Update: Read isdeleted from db and update the base class 
            m_isDeleted = Conversions.ToBoolean(Interaction.IIf(row["IsPanelDeleted"] is DBNull, false, row["IsPanelDeleted"]));

            m_spmStatus = Conversions.ToInteger(row["PanelSPMStatus"]);
            m_parentTestCode = Conversions.ToString(row["PanelParentTestCode"]);


            FlagClean();

        }

        internal void Update()
        {

            Logger.Debug($"{PanelCode} Panel Start Saving....");

            if (base.IsDirty)
            {

                var da = new DataWrapper(Configuration.ConnectionString);
                var paramList = new List<DbParameter>();

                // 'The date is reset in the update statement so that dates are consistent and do not come from the client application.
                // If m_resetReleaseDate Then m_releaseDate = DateTime.Now()

                paramList.Add((DbParameter)da.CreateParameter("@ReportAnalytePanelId", DbType.Int64, m_id, ParameterDirection.InputOutput));
                paramList.Add((DbParameter)da.CreateParameter("@ReportId", DbType.Int64, m_parent.ID));
                paramList.Add((DbParameter)da.CreateParameter("@PanelCode", DbType.String, m_panelCode));
                paramList.Add((DbParameter)da.CreateParameter("@TransmitStatus", DbType.Int32, m_transmitStatus));
                paramList.Add((DbParameter)da.CreateParameter("@OrderingPanelCode", DbType.String, string.Join(",", m_orderingPanelCodes.ToArray())));
                paramList.Add((DbParameter)da.CreateParameter("@CriticalType", DbType.Int32, m_criticalType)); // aaa'
                paramList.Add((DbParameter)da.CreateParameter("@IsPreliminaryReleased", DbType.Boolean, m_isPreliminaryReleased));
                paramList.Add((DbParameter)da.CreateParameter("@MarkedAsPreliminary", DbType.Boolean, m_markedAsPreliminary));
                paramList.Add((DbParameter)da.CreateParameter("@ResetReleaseDate", DbType.Boolean, m_resetReleaseDate));
                if (m_releaseDate > DateTime.Parse("1900-01-01"))
                    paramList.Add((DbParameter)da.CreateParameter("@ReleaseDate", DbType.DateTime, m_releaseDate));
                paramList.Add((DbParameter)da.CreateParameter("@ToFollowSent", DbType.Boolean, m_toFollowSent));
                paramList.Add((DbParameter)da.CreateParameter("@IsDeleted", DbType.Boolean, m_isDeleted));
                paramList.Add((DbParameter)da.CreateParameter("@SPMOrderTestId", DbType.Int64, m_SPMOrderTestId));
                paramList.Add((DbParameter)da.CreateParameter("@SPMStatus", DbType.Int32, m_spmStatus));
                paramList.Add((DbParameter)da.CreateParameter("@ParentTestCode", DbType.String, m_parentTestCode));

                DbParameter[] @params = paramList.ToArray();

                m_id = Conversions.ToLong(da.ExecuteNonQuery("lis_ReportAnalytePanel_Save", @params)["@ReportAnalytePanelId"].Value);

            }

            // Call this before FlagClean is called so that the ObjectLookupId can be set correctly from the RefAnalytePanel
            if (IsNew)
            {
                UpdateReferenceAnalytePanel();
                // m_panel.Update()
            }

            Analytes.Update();
            m_auditItemList.AddRange(Analytes.GetAuditItems());

            Comments.Update();
            m_auditItemList.AddRange(Comments.GetAuditItems());

            // NA 2/27/2014 : reset the original status on each panel component
            Analytes.SetOrigResultStatus();

            Logger.Debug($"{PanelCode} Panel Save Completed. Start Audit...");

            m_auditItemList.AddRange(GetAuditItemsAndClean(true));
            // Me.FlagClean(True)

            Logger.Debug($"{PanelCode} Panel Audit Completed.");

        }

        private void UpdateReferenceAnalytePanel()
        {

            Logger.Debug($"{PanelCode} Start update Ref Panel...");

            // 'This is using the old update method where the refanalyte and mapping are updated in the same proc
            if (Configuration.AppSettings.GetBool("Bioreference.LIS:AddTestFromTestMaster"))
            {

                m_panel.UpdateCombined();
            }

            else
            {

                bool mapRef = m_panel.IsNew; // If RefAnalytePanel is new (new ReportAnalytePanel) or it is updated below, we need to remap

                // The reference analyte CAN be updated, ie. sendout send update analyte values.
                if (m_panel.Id == 0L || m_panel.IsDirty)
                {
                    m_panel.UpdateCore();
                    mapRef = true;
                }

                if (mapRef) // For a new ReportAnalyte or update of RefAnalyte, need to map RefAnalyte
                {
                    m_panel.Update();
                }

            }

            Logger.Debug($"{PanelCode} Ref Panel update Complete.");

        }

        internal void Delete()
        {

            var da = new DataWrapper(Configuration.ConnectionString);
            var @param = new DbParameter[1];

            @param[0] = (DbParameter)da.CreateParameter("@ReportAnalytePanelId", DbType.Int64, m_id);

            da.ExecuteNonQuery("lis_ReportAnalytePanel_Delete", @param);

            // 'Need to call update, comments can be added on deleted Analytes:)
            Comments.Update();

            FlagDeleted();
            m_auditItemList.AddRange(GetAuditItemsAndClean());
            // Me.FlagClean()

        }

